// @ts-check
import { deleteImage, saveImage } from "./branding-image.js";

/** Only names generated by `saveFavicon` are ever read back, deleted or exposed. */
export const FAVICON_FILE_RE = /^favicon-[0-9a-f-]{36}\.(png|jpg|webp|svg)$/;

/** @type {import('./branding-image.js').ImageKind} */
const KIND = { prefix: "favicon", fileCol: "faviconFile", re: FAVICON_FILE_RE };

/**
 * @param {number} id
 * @param {{ userId: number, nickname: string }} consumer
 * @param {{ buffer: Buffer, ext: string }} favicon
 */
export const saveFavicon = (id, consumer, favicon) =>
  saveImage(KIND, id, consumer, favicon);

/**
 * @param {number} id
 * @param {{ userId: number, nickname: string }} consumer
 */
export const deleteFavicon = (id, consumer) => deleteImage(KIND, id, consumer);
